using System.Text.Json;
namespace DeskCanvas.Core;
// v19 migration/recovery behavior is retained verbatim; layer normalization is appended only after it is safe to do so.
public sealed class LayoutRepository
{
 private static readonly JsonSerializerOptions JsonOptions=new(){WriteIndented=true,PropertyNameCaseInsensitive=true};private readonly string root,layoutPath,backupDirectory;
 public LayoutRepository(string root){this.root=root;layoutPath=Path.Combine(root,"layout.json");backupDirectory=Path.Combine(root,"Backups");}
 public CanvasLayout Load(){Directory.CreateDirectory(root);Directory.CreateDirectory(backupDirectory);var current=TryRead(layoutPath);if(current is not null){var migrated=current.Version<2;if(migrated){var known=LatestV2Backup();if(known is not null)MergeLegacyBuiltIns(current,known);else InferLegacyBuiltIns(current);}return Normalize(current,migrated);}foreach(var path in Directory.EnumerateFiles(backupDirectory,"*.json").OrderByDescending(File.GetLastWriteTimeUtc)){var recovered=TryRead(path);if(recovered is not null)return Normalize(recovered,recovered.Version<2);}return new CanvasLayout();}
 public void Save(CanvasLayout layout){Directory.CreateDirectory(root);Directory.CreateDirectory(backupDirectory);layout.Items=LayerOrderMath.Normalize(layout.Items);var temp=layoutPath+".tmp";File.WriteAllText(temp,JsonSerializer.Serialize(Normalize(layout,false),JsonOptions));if(File.Exists(layoutPath))File.Copy(layoutPath,Path.Combine(backupDirectory,$"layout-{DateTime.UtcNow:yyyyMMdd-HHmmss-fff}.json"),true);File.Move(temp,layoutPath,true);PruneBackups();}
 private CanvasLayout? LatestV2Backup(){foreach(var path in Directory.EnumerateFiles(backupDirectory,"*.json").OrderByDescending(File.GetLastWriteTimeUtc)){var item=TryRead(path);if(item?.Version>=2)return item;}return null;}
 private static void MergeLegacyBuiltIns(CanvasLayout legacy,CanvasLayout known){var previous=known.Items.Where(item=>item.Id!=Guid.Empty).GroupBy(item=>item.Id).ToDictionary(group=>group.Key,group=>group.First());foreach(var item in legacy.Items){if(!previous.TryGetValue(item.Id,out var source))continue;item.ContentKind=source.ContentKind;item.Theme=source.Theme;item.DecorationMode=source.DecorationMode;item.Clock=source.Clock?.Clone()??new ClockOptions();item.NowPlaying=source.NowPlaying?.Clone()??new NowPlayingOptions();item.SystemMonitor=source.SystemMonitor?.Clone()??new SystemMonitorOptions();}InferLegacyBuiltIns(legacy);}
 private static void InferLegacyBuiltIns(CanvasLayout layout){foreach(var item in layout.Items){if(string.IsNullOrWhiteSpace(item.StoredFileName))item.ContentKind=item.DisplayName switch{"再生中"=>CanvasContentKinds.NowPlaying,"時計"=>CanvasContentKinds.Clock,"システムモニター" or "システムステータス"=>CanvasContentKinds.SystemMonitor,_=>item.ContentKind};if(item.ContentKind==CanvasContentKinds.Image&&Path.GetExtension(item.StoredFileName).Equals(".gif",StringComparison.OrdinalIgnoreCase))item.ContentKind=CanvasContentKinds.Gif;}}
 private static CanvasLayout Normalize(CanvasLayout layout,bool migrated){layout.Version=2;layout.Settings??=new CanvasSettings();layout.Items??=[];layout.Items=layout.Items.Where(item=>item is not null&&CanvasContentKinds.IsSupported(item.ContentKind)).ToList();var ids=new HashSet<Guid>();foreach(var item in layout.Items){if(item.Id==Guid.Empty||!ids.Add(item.Id)){item.Id=Guid.NewGuid();ids.Add(item.Id);}item.DisplayName??="";item.StoredFileName??="";item.MonitorDevice??="";item.DecorationMode=DecorationModes.IsSupported(item.DecorationMode)?item.DecorationMode:DecorationModes.None;item.Theme=Enum.IsDefined(item.Theme)?item.Theme:WidgetThemeKind.Auto;item.Clock??=new ClockOptions();item.NowPlaying??=new NowPlayingOptions();item.SystemMonitor??=new SystemMonitorOptions();if(!Enum.IsDefined(item.Clock.Style))item.Clock.Style=ClockStyle.Digital;if(!Enum.IsDefined(item.NowPlaying.ProgressStyle))item.NowPlaying.ProgressStyle=NowPlayingProgressStyle.Simple;if(migrated&&item.ContentKind==CanvasContentKinds.SystemMonitor&&item.Height<320){item.Width=Math.Max(320,item.Width);item.Height=Math.Max(390,item.Height);}item.Width=item.Width;item.Height=item.Height;item.Opacity=item.Opacity;item.RotationDegrees=item.RotationDegrees;}layout.Items=LayerOrderMath.Normalize(layout.Items);return layout;}
 private static CanvasLayout? TryRead(string path){try{if(!File.Exists(path))return null;using var document=JsonDocument.Parse(File.ReadAllText(path));if(document.RootElement.ValueKind!=JsonValueKind.Object)return null;var properties=new Dictionary<string,JsonElement>(StringComparer.OrdinalIgnoreCase);foreach(var property in document.RootElement.EnumerateObject())if(!string.Equals(property.Name,"items",StringComparison.OrdinalIgnoreCase))properties[property.Name]=property.Value.Clone();using var empty=JsonDocument.Parse("[]");properties["items"]=empty.RootElement.Clone();var layout=JsonSerializer.Deserialize<CanvasLayout>(JsonSerializer.Serialize(properties),JsonOptions)??new CanvasLayout();var items=document.RootElement.EnumerateObject().FirstOrDefault(property=>string.Equals(property.Name,"items",StringComparison.OrdinalIgnoreCase)).Value;if(items.ValueKind==JsonValueKind.Array)foreach(var entry in items.EnumerateArray())try{var item=entry.Deserialize<CanvasItem>(JsonOptions);if(item is not null)layout.Items.Add(item);}catch(JsonException){}return layout;}catch(JsonException){return null;}catch(IOException){return null;}}
 private void PruneBackups(){foreach(var old in Directory.EnumerateFiles(backupDirectory,"*.json").OrderByDescending(File.GetLastWriteTimeUtc).Skip(10))try{File.Delete(old);}catch(IOException){}}
}
